<?php
declare(strict_types=1);
require_once __DIR__ . '/../functions/helpers.php';
require_role('admin');
$id=(int)($_GET['id']??0);
$stmt=db()->prepare('SELECT o.*,u.name AS account_name,u.email FROM orders o INNER JOIN users u ON u.id=o.user_id WHERE o.id=? LIMIT 1');$stmt->execute([$id]);$order=$stmt->fetch();
if(!$order){set_flash('error','Order not found.');redirect('admin/orders.php');}
$stmt=db()->prepare('SELECT oi.*,p.image FROM order_items oi LEFT JOIN products p ON p.id=oi.product_id WHERE oi.order_id=? ORDER BY oi.id');$stmt->execute([$id]);$items=$stmt->fetchAll();$statusOptions=['pending','processing','shipped','completed','cancelled'];$flash=get_flash();
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Order #<?=intval($id)?> | Admin</title><link rel="stylesheet" href="../css/style.css"><link rel="stylesheet" href="../css/admin.css"></head><body class="admin-page"><header class="admin-header"><a href="../index.php"><img src="../assets/images/logo-placeholder.svg" alt="Gonzaga's Apparel"></a><div><a href="dashboard.php">DASHBOARD</a><a href="orders.php">ORDERS</a><form action="../logout.php" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><button type="submit">LOG OUT</button></form></div></header><main class="admin-shell"><div class="section-kicker">ORDER DETAILS <span></span></div><h1>ORDER #<?=intval($id)?></h1><?php if($flash):?><div class="alert <?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif;?><section class="admin-card order-detail-grid"><div><h2>CUSTOMER</h2><p><strong><?=e($order['account_name'])?></strong><br><?=e($order['email'])?><br><?=e($order['shipping_phone'])?></p><h2>SHIPPING</h2><p><?=e($order['shipping_address1'])?><br><?=($order['shipping_address2']?e($order['shipping_address2']).'<br>':'')?><?=e($order['shipping_city'])?>, <?=e($order['shipping_province'])?> <?=e($order['shipping_postal_code'])?><br><?=e($order['shipping_country'])?></p></div><div><h2>STATUS</h2><form action="order_update.php" method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><select name="status"><?php foreach($statusOptions as $s):?><option value="<?=e($s)?>" <?=$order['status']===$s?'selected':''?>><?=e(ucfirst($s))?></option><?php endforeach;?></select><button type="submit">UPDATE</button></form><p>Payment: <strong><?=e($order['payment_method']==='cod'?'Cash on Delivery':'Bank Transfer')?></strong><br>Placed: <?=e($order['created_at'])?></p></div></section><section class="admin-card"><h2>ITEMS</h2><div class="table-wrap"><table><thead><tr><th>PRODUCT</th><th>PRICE</th><th>QTY</th><th>SUBTOTAL</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?=e($item['product_name'])?></td><td><?=money((float)$item['unit_price'])?></td><td><?=intval($item['quantity'])?></td><td><?=money((float)$item['subtotal'])?></td></tr><?php endforeach;?></tbody></table></div><div class="order-total"><span>SUBTOTAL <?=money((float)$order['subtotal_amount'])?></span><span>SHIPPING <?=$order['shipping_fee']>0?money((float)$order['shipping_fee']):'FREE'?></span><strong>TOTAL <?=money((float)$order['total_amount'])?></strong></div><?php if($order['notes']):?><p><strong>Notes:</strong> <?=e($order['notes'])?></p><?php endif;?></section></main></body></html>
